int register_ppp_channel(struct net *net, struct ppp_channel *chan) {
    struct ppp_channel *new_chan = NULL;

    if (!net || !chan) {
        return -EINVAL;
    }

    new_chan = kmalloc(sizeof(*new_chan), GFP_KERNEL);
    if (!new_chan) {
        return -ENOMEM;
    }

    memset(new_chan, 0, sizeof(*new_chan));

    spin_lock_bh(&net->ppp_lock);

    new_chan->next = net->channels;
    net->channels = new_chan;
    net->channel_count++;

    spin_unlock_bh(&net->ppp_lock);

    return 0;
}
